D=json.loads((ROOT/'data/clean/dashboard.json').read_text());S=json.loads((ROOT/'content/series.json').read_text());E=json.loads((ROOT/'models/evaluation.json').read_text());T=summary(D)
GREEN=colors.HexColor('#214e3c');PALE=colors.HexColor('#edf2e6');GRAY=colors.HexColor('#657363');INK=colors.HexColor('#253b30')
styles=getSampleStyleSheet()
