styles.add(ParagraphStyle(name='LabelR',fontName='Helvetica-Bold',fontSize=10,leading=15,textColor=GREEN,spaceAfter=8))
def normal(s):return str(s).replace('’',"'").replace('“','"').replace('”','"').replace('–','-').replace('—','-').replace('…','...')
def p(t,style='BodyR'):return Paragraph(html.escape(normal(t)).replace('\n','<br/>'),styles[style])
def h(t):return p(t,'HeadR')
def label(t):return p(t,'LabelR')
def foot(canvas,doc):
 canvas.saveState();canvas.setStrokeColor(colors.HexColor('#dfe6d6'));canvas.line(46,43,549,43);canvas.setFillColor(GRAY);canvas.setFont('Helvetica',8);canvas.drawString(46,29,'RELATE / SEEN & UNDERSTOOD / DEMONSTRATION CAMPAIGN');canvas.drawRightString(549,29,str(doc.page));canvas.restoreState()
def table(rows,widths):
 tbl=Table([[p(v,'SmallR') for v in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
 tbl.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PALE),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),9),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('LINEBELOW',(0,0),(-1,-1),.5,colors.HexColor('#e1e8da'))]))
 return tbl
def doc(name,flow):SimpleDocTemplate(str(ROOT/'reports'/name),pagesize=A4,rightMargin=46,leftMargin=46,topMargin=48,bottomMargin=62,title=name.replace('-',' ').replace('.pdf',''),author='Relate project').build(flow,onFirstPage=foot,onLaterPages=foot)
posts=D['posts'];cs=D['comments'];views=sum(p['views'] for p in posts);reach=sum(p['reach'] for p in posts);actions=sum(p[k] for p in posts for k in ['likes','comments','shares','saves']);rel=sum(c['label']=='Relatable' for c in cs);follows=sum(p['followers_gained'] for p in posts)
exp=json.loads((ROOT/'reports/analysis.json').read_text())
a=exp['experiment'];corr=exp['correlation']
flow=[p('RELATE / RESEARCH & STRATEGY','LabelR'),Spacer(1,50),p('Understand what\nconnects.','TitleR'),p('The Data-Driven Social Engagement Initiative','HeadR'),p('A complete demonstration study of growth, audience relatability, content experiments and creative strategy.','SubR'),Spacer(1,24),table([['CAMPAIGN','SCOPE'],['Seen & Understood','24 post records / 12 original concepts / 6 topics'],['Observation period','1 October - 4 November 2026; each post measured at 168 hours'],['Comment sample','720 synthetic comments; 30 per post'],['Data provenance','Seeded synthetic data (seed 42). No posts were published and no audience was observed.']],[150,353]),Spacer(1,24),p('Prepared 25 November 2026. This report demonstrates a reproducible analytical workflow. Every campaign conclusion is conditional on the synthetic data-generating assumptions, not evidence about real people.','SmallR'),PageBreak(),
h('What the campaign tells us'),p(f'The demonstration contains {views:,} views, {follows:,} post-attributed follower gains and {actions/reach:.1%} aggregate engagement. The classifier marks {rel:,} of {len(cs):,} sampled comments as Relatable ({rel/len(cs):.1%}). These are simulated totals.'),
label('Connection and propagation answer different questions'),p('Social anxiety has the highest share of Relatable labels (80.0%). Burnout has the highest weighted viral score (14.51). A high relatability rate describes the comment sample; a high viral score describes weighted engagement actions. Neither alone measures lasting community connection.'),
table([['Topic','Relatable','Viral score','Follows']]+[[r['topic'],f"{r['relatable_rate']:.1%} (n={r['analyzed_comments']})",f"{r['viral_score']:.2f}",str(r['followers_gained'])] for r in T],[150,140,108,105]),Spacer(1,18),p('All topics have four post records and 120 analyzed comments. This balanced sample is convenient for demonstration, but does not represent an organic audience distribution. Rates should be recomputed after importing real data.','SmallR'),PageBreak(),
h('How the evidence is measured'),label('The metrics'),table([['Measure','Definition and interpretation'],['Engagement rate','(Likes + reported comments + shares + saves) / sum of post reach. Reach is not deduplicated across posts.'],['Weighted viral score','100 x (3 x shares + 2 x saves + likes) / reach. Weights are project assumptions. This is a descriptive proxy, not a probability or a reproduction coefficient.'],['Relatability','Predicted Relatable / all analyzed nonempty comments. Neutral includes questions, criticism and non-relatable reactions.'],['Save-to-share ratio','Saves / shares. Undefined when shares are zero. It does not identify the precise moment of connection.'],['Growth','Sum of post-attributed followers gained. Does not subtract unfollows and is not net account growth.'],['Retention','View-weighted mean of post retention_rate; consistent completion definitions are required across platforms.']],[145,358]),Spacer(1,16),p(f'Across the 24 synthetic post records, Pearson correlation between model relatability rate and attributed follows is {corr:.3f}. This is an unadjusted association confounded by reach, topic and platform. It is not a causal effect.'),p('The 720 analyzed comments cover 44.4% of 1,623 reported comments. Wilson intervals describe binomial uncertainty in model labels only. Correlated comments, sampling bias and model error make real-world uncertainty larger.','SmallR'),PageBreak(),
h('What the hook experiment supports'),p('Each concept has two variants: A opens with text; B opens with an acted point-of-view scene. Topic, platform, format, duration and observation window are matched. In the demo, all 12 concept pairs are complete.'),
table([['Result','Value'],['Unit of analysis','One matched content pair; 12 pairs'],['Primary outcome','Shares divided by reach'],['Mean B - A difference',f"{a['mean']*100:.3f} percentage points"],['Two-sided exact sign-flip p-value',f"{a['p']:.4f}"],['95% pair-bootstrap interval',f"{a['interval'][0]*100:.3f} to {a['interval'][1]*100:.3f} percentage points"]],[245,258]),Spacer(1,14),p('The comparison is '+('inconclusive at the 0.05 threshold.' if a['p']>=.05 else 'below the preselected 0.05 threshold within the synthetic data.')+' The exact test enumerates 4,096 sign assignments. The interval uses 2,000 seeded bootstrap resamples of pairs. Both assume meaningful matched observations. The percentile interval and permutation test use different approximations and can disagree near a threshold; the preselected permutation p-value drives the conclusion.'),label('Protocol for a real campaign'),p('Pre-register share rate, the minimum useful effect and a sample-size plan using baseline variability. Randomize non-overlapping audiences where possible. Otherwise repeat matched posting-time blocks and describe the analysis as observational. Keep captions and the final 22 seconds fixed. Wait 168 hours for every post, then analyze once. A/B duration, hook and posting time in separate experiments; do not change all three together.'),p('Organic sequential posts can be affected by time, recommendation algorithms, carryover and audience composition. Synthetic data cannot demonstrate a causal creative effect.','SmallR'),PageBreak(),
h('The next campaign to run'),table([['Slot','Creative','Purpose / measure'],['Monday','C01: The conversation after the conversation','Social anxiety anchor. Compare A/B hooks; share rate is primary.'],['Wednesday','C03: Rest does not need a receipt','Burnout anchor. Track saves, shares and human-reviewed relatability.'],['Friday','C05: A timeline of your own','Self-comparison challenger. Replicate the format and observation window.'],['Sunday','C02: The phone-call rehearsal','Second social anxiety piece. Test whether topic ranking replicates.']],[75,208,220]),Spacer(1,17),label('Creative choices that still need testing'),p('Use the supplied 25-second scripts as the starting point. Every demo post has the same duration, so this dataset cannot show that 25 seconds is optimal. Caption style and posting time are not independently varied. Test each in a later, separately planned experiment.'),label('Trend forecasting'),p('The dashboard fits a line to topic interest indices against elapsed days and extrapolates seven days, clipping to 0-100. At least four weekly observations are required. A last-point backtest fits all but the last point and reports the absolute error on the last observed value. The demo indices are simulated, not fetched from a trend service. For real use, import a consistently normalized weekly series and record its source.'),label('Decision rules'),p('Prioritize topics only after human review confirms the signal across repeated posts. Review both connection and sharing. Stop expanding a topic if the signal is driven by a few comments, platform mix, or inconsistent observation windows. Save raw exports and the cleaning audit so the decision can be reproduced.'),PageBreak(),
h('Model quality and reproducibility'),p(f'The NLP baseline is multinomial naive Bayes using word unigrams and bigrams, Laplace smoothing alpha = 1, and a 0.5 threshold. It trains on 120 author-labeled English comments and is evaluated on 36 separately authored held-out examples. Accuracy: {E["accuracy"]:.1%}; Relatable precision: {E["precision"]:.1%}; recall: {E["recall"]:.1%}; F1: {E["f1"]:.3f}.'),table([['Expected / predicted','Neutral','Relatable'],['Neutral','15','3'],['Relatable','1','17']],[225,139,139]),Spacer(1,15),label('Errors are part of the deliverable'),p('The model misreads “I never struggle with this issue” as Relatable and misses “That is my entire week in a sentence.” The evaluation JSON preserves all four errors. Posterior scores are not calibrated probabilities. Negation, sarcasm, multilingual comments and unfamiliar terms require human review.'),label('Data processing'),p('The pipeline normalizes Unicode and whitespace, removes URLs from comment text, deduplicates matching IDs, rejects conflicting IDs and orphan comments, validates numeric/date bounds, tags comments and produces CSV/JSON outputs. The demo audit removes one duplicate post, one duplicate comment and one empty comment.'),label('Reproduce the study'),p('1. python3 python/create_corpus.py\n2. python3 python/sentiment.py --train\n3. python3 python/generate_demo.py\n4. python3 python/pipeline.py --source synthetic_demo\n5. node python/analysis.mjs\n6. python3 python/make_reports.py\n7. npm test && npm run build','SmallR'),p('PDF generation requires ReportLab. Model inference and the data pipeline use the Python standard library. The website is static HTML, CSS and JavaScript with no external runtime dependencies. The bundled README and methodology document provide the import schema and deployment procedure.','SmallR')]
